import{z as o,x as l,o as t,c as d,q as s,j as A,D as E,d as r,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"主动份额","description":"","frontmatter":{"title":"主动份额","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/active-share.md","filePath":"quant/active-share.md","lastUpdated":1791413859000}'),D={name:"quant/active-share.md"};function p(h,a,m,c,T,u){const B=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="主动份额" tabindex="-1">主动份额 <a class="header-anchor" href="#主动份额" aria-label="Permalink to &quot;主动份额&quot;">​</a></h1><div class="epigraph"><p>跟踪误差度量的是收益偏离的波动；主动份额度量的是持仓与基准的重量差。可以高 TE 低主动份额（杠杆因子赌注），也可以低 TE 高主动份额（对冲掉的选股）。</p><footer>—— Cremers and Petajisto, How Active Is Your Fund Manager? A New Measure That Predicts Performance, Review of Financial Studies, 2009</footer></div><p><a href="/quant/benchmark-tracking-error">上一课</a>把契约钉在 TE 上。主动份额（active share）的缺口是<strong>持仓层的偏离</strong>：\\(\\tfrac12\\sum_i|w_{p,i}-w_{b,i}|\\)。Cremers–Petajisto 用它区分橱窗指数（closet indexer）与真正主动。本课写它与 TE、与 <a href="/quant/brinson">Brinson</a> 的分工，以及它<strong>不</strong>保证 alpha——高主动份额也可以是分散很差的错误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TE 可来自几只期货或行业倾斜，持仓仍与指数高度重叠。主动份额高意味着名字层面不同，但可以用空头或对冲把 TE 压低（多空）。问题是产品识别：收主动费却主动份额接近零，是契约问题；主动份额高却持续负 IR，是技能问题。Petajisto 后续把基金分成因子赌注 vs 选股。不要把主动份额当新的定价因子去对 <a href="/quant/capm">CAPM</a> 回归；它是治理度量。</p><p><span class="marginnote">用数字过一遍公式：若组合相对基准只把 10% 的权重从 A 挪到基准外的 B，主动份额就是 \\(\\tfrac12(|0.10|+|0.10|)=10\\%\\)——所有权重差取绝对值加总再除以二。纯复制时和为零、份额为零；组合 100% 押一只基准外股票时达到最大值 \\(100\\%\\)。</span></p><p>与 130/30：空头增加主动份额，也增加借券。与股票多空中性：相对现金的主动份额无定义，应相对对冲基准或零。</p><h3 id="基准一换-份额就变" tabindex="-1">基准一换，份额就变 <a class="header-anchor" href="#基准一换-份额就变" aria-label="Permalink to &quot;基准一换，份额就变&quot;">​</a></h3><p>用错基准会把风格暴露当成主动份额（小盘基金对标普 500）。必须与 TE 课同一套可投资基准。衍生品、空头、未分类现金要有处理规则，否则一半份额只是会计。</p><p><span class="marginnote">Cremers–Petajisto 的预测力在后续样本有争议。即便预测力减弱，橱窗指数识别仍然有用：那是费用是否该收主动价的证据，不必依赖 alpha 预测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计算：持仓与基准权重对齐到同一分类与时点。分解：行业内 vs 行业间（接近 Brinson 配置/选择）。对照：主动份额 vs 事后 TE vs 净 IR。阈值：极低则疑为橱窗；极高则查集中度与容量。ETF 化的因子产品主动份额可以高，那是规则暴露，不是选股。</p><p><span class="marginnote">「橱窗指数」（closet indexer）指收着主动管理费、持仓却几乎复制指数的基金：主动份额极低、TE 极小。识别它的意义在于费用审查——指数化成本只有几个基点，为复制组合付一百基点以上的主动费，是契约层面的错配。</span></p>',13)),(t(),A(i,null,{default:E(()=>[n(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%BB%E5%8A%A8%E4%BB%BD%E9%A2%9D%E4%B8%8E%20TE%20%E7%9A%84%E7%BB%84%E5%90%88%E6%98%AF%E4%BB%80%E4%B9%88%22%5D%20--%3E%20A%5B%22%E4%BD%8E%E4%BB%BD%E9%A2%9D%20%E4%BD%8E%20TE%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E4%BD%8E%E4%BB%BD%E9%A2%9D%20%E9%AB%98%20TE%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E9%AB%98%E4%BB%BD%E9%A2%9D%20%E4%BD%8E%20TE%22%5D%0A%20%20Q%20--%3E%20D%5B%22%E9%AB%98%E4%BB%BD%E9%A2%9D%20%E9%AB%98%20TE%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E8%BF%91%E4%BC%BC%E5%A4%8D%E5%88%B6%20%E7%96%91%E6%A9%B1%E7%AA%97%E6%8C%87%E6%95%B0%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E6%9C%9F%E8%B4%A7%E6%88%96%E6%9D%A0%E6%9D%86%E5%81%9A%E7%9A%84%E5%9B%A0%E5%AD%90%E8%B5%8C%E6%B3%A8%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E5%AF%B9%E5%86%B2%E6%8E%89%E7%9A%84%E9%80%89%E8%82%A1%20%E5%A4%9A%E7%A9%BA%E7%BB%93%E6%9E%84%22%5D%0A%20%20D%20--%3E%20D2%5B%22%E7%9C%9F%E9%9B%86%E4%B8%AD%E9%80%89%E8%82%A1%20%E6%88%96%E9%9B%86%E4%B8%AD%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"这张图回答的问题是：只看主动份额或只看 TE 都分不清基金类型，两个度量放在同一张象限里才能区分复制、因子赌注与选股。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"委托需要同时看「离基准多远」（份额）和「收益晃多厉害」（TE）。两者一起才能分清：在复制、在赌因子、还是在选股。费用应匹配真实主动；生命周期里，拥挤策略的主动份额可以仍高，IR 已经没了。",-1)),(t(),A(i,null,{default:E(()=>[n(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E5%B7%AE%E7%BB%9D%E5%AF%B9%E5%80%BC%22%5D%20--%3E%20AS%5B%22%E4%B8%BB%E5%8A%A8%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20R%5B%22%E4%B8%BB%E5%8A%A8%E6%94%B6%E7%9B%8A%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20TE%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20AS%20--%3E%20Closet%5B%22%E4%BD%8E%E4%BB%BD%E9%A2%9D%20%E6%A9%B1%E7%AA%97%E6%8C%87%E6%95%B0%22%5D%0A%20%20TE%20--%3E%20Factor%5B%22%E9%AB%98%20TE%20%E6%88%96%E4%B8%BA%E5%9B%A0%E5%AD%90%E6%9D%A0%E6%9D%86%22%5D%0A%20%20AS%20--%3E%20Stock%5B%22%E9%AB%98%E4%BB%BD%E9%A2%9D%20%E9%80%89%E8%82%A1%E6%88%96%E9%9B%86%E4%B8%AD%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>持仓披露滞后使实时主动份额不可得。对冲基金不披露持仓时，度量退回 TE 与因子暴露。下一课改收益会计：即使持仓主动，现金流也会改写「赚了多少」。</p><p><span class="marginnote">初学者容易以为主动份额越高说明经理水平越高；它其实只度量「敢偏离」，不度量「偏得对不对」。高份额配上持续负 IR，恰恰是分散很差的错误赌注的证据——份额要和 IR、集中度一起读才有结论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主动份额是持仓偏离，TE 是收益偏离，二者不可替代。</li><li>用途首先是识别橱窗指数与费用是否匹配。</li><li>高份额不蕴含正 IR，须与集中度和成本一起看。</li><li>出处：Cremers and Petajisto, <em>RFS</em>, 2009；Petajisto 对因子赌注 vs 选股的分类。</li></ul>',5))])}const C=o(D,[["render",p]]);export{_ as __pageData,C as default};
